import{z as r,x as s,o as A,c as d,q as i,j as l,D as B,d as t,s as n,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const I=JSON.parse('{"title":"KV 量化：INT8 与 INT4","description":"","frontmatter":{"title":"KV 量化：INT8 与 INT4","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-quant-int8-int4.md","filePath":"llm/kv-quant-int8-int4.md","lastUpdated":1791413859000}'),p={name:"llm/kv-quant-int8-int4.md"};function D(m,E,C,F,k,f){const e=s("Mermaid");return A(),d("div",null,[E[2]||(E[2]=i('<h1 id="kv-量化-int8-与-int4" tabindex="-1">KV 量化：INT8 与 INT4 <a class="header-anchor" href="#kv-量化-int8-与-int4" aria-label="Permalink to &quot;KV 量化：INT8 与 INT4&quot;">​</a></h1><div class="epigraph"><p>压缩 KV 的第一刀不改注意力看得见什么，只改每个数字占几个比特；刀钝与否，取决于键和值愿不愿意被当成权重对待。</p><footer>—— 据 Liu et al., KIVI, ICML 2024 对 KV 元素分布与量化轴的分析整理</footer></div><p><a href="/llm/kv-prefix-cache">上一课</a>把相同的计算付一次，但每一份缓存仍按 FP16 宽度计费。本课进入压缩单元：量化是四刀里最钝也最稳的一刀——不改可见集、不改模型，只改缓存里存的数字与读出来的方式。8-bit 档的尺度、轴与核边界已在 <a href="/llm/kv-int8-fp8">KV INT8/FP8</a> 写过，2-bit 的免调非对称方案在 <a href="/llm/kivi">KIVI</a>。本课收在 INT8 与 INT4 两档的选型：何时一字节已够，何时必须半字节，代价落在哪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把元素宽度从 2 字节打到 1 字节，同样预算下长度或并发翻倍；打到 0.5 字节再翻一倍。但 KV 不是权重：权重离线、可校准、分布稳；KV 在线追加、带激活异常值。键沿通道常有固定的大幅度通道，尺度被它们绑架后，其余通道的量化阶梯粗到不可用——对称逐张量的 4-bit 在第一步就会崩。另一头，8-bit 的保护带宽可能过剩：逐 token 尺度的 INT8 在很多模型上几乎无感。选型的实质是：误差预算、元数据开销与核支持三者的交点，而不是比特越少越好。</p><p><span class="marginnote">数字实例：每 token 128 KiB 的会话（Llama-3-8B 口径），128K 上下文一条在 FP16 下约 16 GiB；打到 INT8 是 8 GiB，打到 INT4 只要 4 GiB。每降一档，同一张卡能同时接待的会话数翻一倍——这就是「容量翻倍」的全部含义，前提是质量不掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>轴与粒度</strong>。经验结论稳定：键按通道量化、值按 token 量化。键的异常集中在少数通道，逐通道各配尺度才不被绑架；值更像随 token 变化的混合系数，逐 token 尺度即可。INT8 走逐 token 或逐块（32–128 token）粒度；INT4 必须非对称仿射加更细的组（逐通道或 64–256 通道一组），并沿通道攒一组 token 再统计——这要求转置访问或分块缓冲，是 4-bit 工程复杂度的真正来源。</p><p><span class="marginnote">常见误区：以为「量化粒度越细一定越好」。粒度细一档，尺度与零点的元数据就多一份，逐通道统计还要转置访问；元数据本身占 HBM 也占带宽。粒度是误差与开销的折中，不是美德。</span></p><p><strong>残差窗口</strong>。最近 \\(R\\) 个 token 留在高精度：当前句的键值对下一步最重要，噪声预算应花在远历史上。\\(R\\) 取几十到几百，量化误差对正在展开的局部上下文免票。</p><p><strong>核兑现</strong>。省的是带宽，不是容量本身：decode 每步把缓存从 HBM 扫进片上，若实现「存 8-bit、读出后先解回 FP16 再算」，显存降了而带宽几乎不降。要吃到红利，需要量化感知的注意力核，或至少在片上完成反量化（机制见 <a href="/llm/kv-int8-fp8">KV INT8/FP8</a> 的 profiler 论证）。</p>',11)),(A(),l(o,null,{default:B(()=>[n(e,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20KV%5B%22%E6%96%B0%20token%20%E7%9A%84%20k%2Cv%22%5D%20--%3E%20AXIS%5B%22%E9%94%AE%E6%8C%89%E9%80%9A%E9%81%93%20%2F%20%E5%80%BC%E6%8C%89%20token%22%5D%0A%20%20AXIS%20--%3E%20SCALE%5B%22%E7%BB%9F%E8%AE%A1%E5%B0%BA%E5%BA%A6%E4%B8%8E%E9%9B%B6%E7%82%B9%EF%BC%88%E9%9D%9E%E5%AF%B9%E7%A7%B0%EF%BC%89%22%5D%0A%20%20SCALE%20--%3E%20W%5B%22%E4%BD%8E%E7%B2%BE%E5%BA%A6%E5%86%99%E7%BC%93%E5%AD%98%EF%BC%8C%E9%99%84%E5%B8%A6%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A%20%20W%20--%3E%20FP%7B%22%E9%A1%B5%E7%9A%84%E7%B2%BE%E5%BA%A6%E6%8C%87%E7%BA%B9%E5%8C%B9%E9%85%8D%3F%22%7D%0A%20%20FP%20--%3E%7C%E5%90%A6%7C%20MISS%5B%22%E4%B8%8D%E5%85%B1%E4%BA%AB%EF%BC%8C%E5%8D%95%E7%8B%AC%E9%87%8F%E5%8C%96%E6%88%96%E9%87%8D%E7%AE%97%22%5D%0A%20%20FP%20--%3E%7C%E6%98%AF%7C%20LOAD%5B%22decode%20%E6%8C%89%E4%BD%8E%E7%B2%BE%E5%BA%A6%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20LOAD%20--%3E%20DQ%5B%22%E7%89%87%E4%B8%8A%E5%8F%8D%E9%87%8F%E5%8C%96%E6%88%96%E4%BD%8E%E7%B2%BE%E5%BA%A6%E7%82%B9%E7%A7%AF%22%5D%0A%20%20DQ%20--%3E%20ATT%5B%22softmax%20%E4%B8%8E%E5%8A%A0%E6%9D%83%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[t("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"误差是加性噪声，进入点积后变成 logit 扰动，再经 softmax 放大或吸收。键的误差直接改注意力分布：softmax 对大 logit 敏感，系统性偏移会挪动注意力的落点，长上下文的针检索最先露馅——针的 logit 优势被噪声稀释。值的误差进输出残差，逐层累积但被均摊，所以值比键耐受，这正是「键按通道、值按 token」的机制根据。8-bit 的误差通常小于 logit 间距，短上下文无感；4-bit 把噪声推到与间距同量级，轴与粒度就不能再省。",-1)),E[5]||(E[5]=a("p",null,[t("量化还牵动共享与调度："),a("a",{href:"/llm/kv-prefix-cache"},"前缀缓存"),t("的指纹必须带精度，FP16 页与 INT4 页不能共享；批量间混布不同精度的请求，会让每步带宽核算与水位预算都对不上账。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：「logit 间距」指注意力打分里候选位置之间的分数差。softmax 像按分数分蛋糕：分差大时，小噪声不改变谁拿大块；分差只有毫厘时，同样的小噪声就能翻转名次。8-bit 的噪声通常小于常见分差，4-bit 的噪声则与之相当，这就是两档手感的来源。")],-1)),(A(),l(o,null,{default:B(()=>[n(e,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20KE%5B%22%E9%94%AE%E7%9A%84%E9%87%8F%E5%8C%96%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20KL%5B%22q%20%E4%B8%8E%20k%20%E7%9A%84%E7%82%B9%E7%A7%AF%20logit%20%E8%A2%AB%E6%89%B0%E5%8A%A8%22%5D%0A%20%20KL%20--%3E%20KS%7B%22%E6%89%B0%E5%8A%A8%E7%9B%B8%E5%AF%B9%20logit%20%E9%97%B4%E8%B7%9D%E5%A4%9A%E5%A4%A7%3F%22%7D%0A%20%20KS%20--%3E%7C%22%E8%BF%9C%E5%B0%8F%E4%BA%8E%E9%97%B4%E8%B7%9D%22%7C%20KO%5B%22softmax%20%E5%90%B8%E6%94%B6%2C%20%E6%B3%A8%E6%84%8F%E5%8A%9B%E5%88%86%E5%B8%83%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8F%98%22%5D%0A%20%20KS%20--%3E%7C%22%E5%90%8C%E9%87%8F%E7%BA%A7%22%7C%20KD%5B%22%E8%90%BD%E7%82%B9%E6%8C%AA%E5%8A%A8%2C%20%E9%95%BF%E4%B8%8A%E4%B8%8B%E6%96%87%E9%92%88%E6%A3%80%E7%B4%A2%E5%85%88%E6%8E%89%22%5D%0A%20%20VE%5B%22%E5%80%BC%E7%9A%84%E9%87%8F%E5%8C%96%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20VO%5B%22%E7%9B%B4%E6%8E%A5%E5%8A%A0%E8%BF%9B%E8%BE%93%E5%87%BA%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20VO%20--%3E%20VA%5B%22%E9%80%90%E5%B1%82%E7%B4%AF%E7%A7%AF%E4%BD%86%E8%A2%AB%E5%9D%87%E6%91%8A%3A%20%E5%80%BC%E6%9B%B4%E8%80%90%E5%8F%97%22%5D%0A%20%20KD%20--%3E%20G%5B%22%E7%BB%93%E8%AE%BA%3A%20%E9%94%AE%E9%85%8D%E9%80%90%E9%80%9A%E9%81%93%E7%BB%86%E8%BD%B4%2C%20%E5%80%BC%E6%8C%89%20token%20%E5%8D%B3%E5%8F%AF%22%5D%0A%20%20VA%20--%3E%20G%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=i('<p><span class="marginnote">Llama-3-8B 的 KV 是 128 KiB/token（FP16，口径见第一课），INT4 打到 32 KiB，同卡理论上多装 4 倍会话。但逐通道尺度与零点是 FP16 元数据，粒度每细一档账本厚一截——净收益是「元素字节 ×4 减元数据」，不是 ×4。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>4-bit 不是安全终点：更极端的 <a href="/llm/kv-fp4">FP4</a> 与 2-bit 需要更强的轴处理与残差窗口，收益也逐档递减。评估不能只看困惑度——短文本 PPL 几乎不动而长上下文任务已掉点，要用针测试与长文档问答验收。GQA 下尺度要聚合到 KV 头，不能按查询头重复统计。混精度共存会破前缀指纹，滚动升级要成批失效旧页。最后，权重量化的经验（<a href="/llm/gptq">GPTQ</a>、<a href="/llm/smoothquant">SmoothQuant</a> 一类校准）不能直接搬给 KV：未来 token 未出现，在线统计才是主路径。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>量化改的是每元素字节与读出方式，不改可见集；decode 的红利在带宽，必须由低精度核兑现。</li><li>轴不对称：键按通道、值按 token，机制是键的异常通道与值的残差角色。</li><li>INT8 逐 token 常已够用；INT4 需要非对称、细粒度与通道攒批，复杂度涨在元数据与访存。</li><li>最近窗口留高精度，误差预算花在远历史。</li><li>精度进前缀指纹；评估看长上下文任务，不只看困惑度。</li><li>出处：Liu et al., KIVI, ICML 2024；8-bit 口径据本仓库 KV INT8/FP8 课；不发明文献。</li></ul>',5))])}const h=r(p,[["render",D]]);export{I as __pageData,h as default};
